def closest_integer(value):
    try:
        num = float(value)
    except ValueError:
        return 0

    floor = int(num)
    ceil = floor + 1

    dist_floor = abs(num - floor)
    dist_ceil = abs(num - ceil)

    if dist_floor < dist_ceil:
        return floor
    elif dist_ceil < dist_floor:
        return ceil
    else:
        if num >= 0:
            return ceil
        else:
            return floor
```

