    # Step 2: Parse input string into a list of characters
    chars = test.split()

    # Step 3: Count frequency of each character
    counts = {}
    for char in chars:
        counts[char] = counts.get(char, 0) + 1

    # Step 4: Find the maximum frequency
    max_count = max(counts.values())

    # Step 5: Filter characters that have the maximum frequency
    result = {}
    for char, count in counts.items():
        if count == max_count:
            result[char] = count

    return result
