def numerical_letter_grade(grades):
    """
    Converts a list of numerical GPAs to letter grades based on a specific threshold table.

    Args:
        grades (list): A list of numerical GPAs (floats or ints).

    Returns:
        list: A list of corresponding letter grades.
    """
    result = []

    for gpa in grades:
        if gpa == 4.0:
            result.append('A+')
        elif gpa > 3.7:
            result.append('A')
        elif gpa > 3.3:
            result.append('A-')
        elif gpa > 3.0:
            result.append('B+')
        elif gpa > 2.7:
            result.append('B')
        elif gpa > 2.3:
            result.append('B-')
