def fix_spaces(text):
    """
    Given a string text, replace all spaces in it with underscores, 
    and if a string has more than 2 consecutive spaces, 
    then replace all consecutive spaces with - 

    fix_spaces("Example") == "Example"
    fix_spaces("Example 1") == "Example_1"
    fix_spaces(" Example 2") == "_Example_2"
    fix_spaces(" Example   3") == "_Example-3"
    """
    if not text:
        return text

    result = []
    space_count = 0

    for char in text:
        if char == ' ':
            space_count += 1
        else:
            # Process accumulated spaces before the current non-space char
            if space_count > 0:
                # If we have 3 or more spaces, replace with a single dash
                if space_count >= 2:
                    result.append('-')
                else:
                    result.append('_' * space_count)
                space_count = 0
            result.append(char)

    # Handle trailing spaces
    if space_count > 0:
        if space_count >= 2:
            result.append('-')
        else:
            result.append('_' * space_count)

    return "".join(result)
